'use strict';
const main=document.querySelector('main');
const A='assets/';
const state={uploads:{},urls:{},scroll:'zju'};
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const asset=(key,fallback)=>state.urls[key]||(fallback?A+fallback:'');
const icons={
 resume:`<svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff9e9" d="m29 14 72-4 3 60-73 4z"/><path fill="#fffdf7" d="m44 7 72 4-3 60-73-4z"/><path d="m55 23 34 2m-34 10 45 2m-46 10 31 2m-32 10 39 2"/><path d="m115 47 16-24 7 5-16 24-11 6z"/><path d="m129 26 7 5m-22 17 7 5"/><path d="m16 18 3-7 3 7 7 3-7 3-3 7-3-7-7-3z"/></svg>`,
 code:`<svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fafcf9" d="m29 15 92 1 3 52-94-1z"/><path d="m19 68 117 1-9 7-97-1zM39 24h74v34H39z"/><path d="m59 35-8 7 8 6m33-13 8 7-8 7m-19-17-6 21"/><path d="m126 10 5-7m3 16 10-3m-3 14 9 4"/></svg>`,
 aigc:`<svg viewBox="0 0 160 80" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fff8f6" d="m27 17 78-8 6 57-77 9z"/><path d="m37 54 17-21 13 11 15-23 17 29M44 27a5 5 0 1 0 0-.1z"/><path fill="#f1d99c" d="m95 61 24-38 8 5-24 38-12 6z"/><path d="m116 27 9 5m-29 29 7 5M124 10v10m-5-5h10m8 27v12m-6-6h12"/></svg>`,
 book:`<svg viewBox="0 0 160 90" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path fill="#fffdf9" d="M26 21c15-6 32-2 47 7 16-9 33-11 53-5l-5 51c-16-5-33-3-48 4-16-8-31-11-49-6z"/><path d="M73 28v50M33 33c11-2 21 0 31 5m-32 5c11-2 21 0 31 5m-32 5c11-2 21 0 31 5m22-20c12-6 22-7 32-5m-32 15c12-6 22-7 32-5m-32 15c12-6 22-7 32-5"/><path d="m129 10 4-7 3 7 8 3-8 3-3 8-4-8-7-3z"/></svg>`
};
function breadcrumb(items=[]){return `<div class="breadcrumb"><a href="#home">← 返回首页</a>${items.map(([label,href])=>`<span>/</span>${href?`<a href="${href}">${esc(label)}</a>`:`<span>${esc(label)}</span>`}`).join('')}</div>`;}
function heading(en,title,desc,note=''){return `<div class="page-heading"><div><span class="eyebrow">${en}</span><h1>${title}</h1><p>${desc}</p></div>${note?`<span class="corner-note">${note}</span>`:''}</div>`;}
function tags(items){return `<div class="tags">${items.map(s=>`<span class="tag">${s}</span>`).join('')}</div>`;}
function figure(src,title,caption='',cls=''){return `<figure class="figure ${cls}"><button data-image="${esc(src)}" data-title="${esc(title)}" aria-label="放大查看${esc(title)}"><img src="${esc(src)}" alt="${esc(title)}" loading="lazy"></button><figcaption><strong>${title}</strong>${caption}</figcaption></figure>`;}
function flow(items){return `<div class="flow">${items.map((s,i)=>`${i?'<i aria-hidden="true">→</i>':''}<span>${s}</span>`).join('')}</div>`;}
function home(){return `<div class="home-topline"><span>PRODUCT × DESIGN × A LITTLE CURIOSITY</span><span>Portfolio, 2026</span></div><div class="home-grid"><section class="profile"><h1>你好，我是<span>李诗璐。</span></h1><div class="profile-inner"><figure class="photo-paper"><img src="${asset('portrait','portrait.png')}" alt="李诗璐的个人照片"><figcaption>Hi, I'm Shilu :)</figcaption></figure><div class="profile-facts"><p class="edu"><b>浙江大学</b>工业设计工程 · 硕士<br>2024 — 2027</p><p><b>米兰理工大学</b>产品服务系统设计 · 交换</p><p><b>东华大学</b>工业设计 · 本科</p></div></div><p class="intro-copy">从设计走向产品，关注<strong>人如何理解和使用技术</strong>。我喜欢从真实问题出发，梳理需求、推敲规则，再把想法做成能使用的东西。</p><div class="profile-tags"><span class="tag">AI 产品</span><span class="tag">用户体验</span><span class="tag">Vibe Coding</span><span class="tag">持续动手中</span></div><div class="profile-note"><svg viewBox="0 0 80 36" fill="none" stroke="currentColor" stroke-width="1.5"><path d="M2 10c30-20 27 31 69 9M59 9l13 10-10 12"/></svg><span>一些工作，也有一些好奇心。</span></div></section><section class="index-wrap" aria-label="作品分类"><div class="index-label">Open a little chapter ↘</div><div class="module-grid"><a class="module-card" href="#internships"><div class="card-art">${icons.resume}</div><h2>实习经历</h2><p>腾讯元宝 · 美团点评<br>携程智行机票</p><span class="module-en">WORK EXPERIENCE</span><span class="arrow" aria-hidden="true">↗</span></a><a class="module-card" href="#vibe"><div class="card-art">${icons.code}</div><h2>Vibe Coding 项目</h2><p>和好喵 · 衣柜设计师<br>把日常问题做成产品</p><span class="module-en">IDEAS INTO PRODUCTS</span><span class="arrow" aria-hidden="true">↗</span></a><a class="module-card" href="#aigc"><div class="card-art">${icons.aigc}</div><h2>AIGC 尝试</h2><p>风格化长卷 · 电商生图<br>从工作流到视觉表达</p><span class="module-en">GENERATIVE EXPLORATIONS</span><span class="arrow" aria-hidden="true">↗</span></a><a class="module-card" href="#design"><div class="card-art">${icons.book}</div><h2>软硬件系统设计作品集</h2><p>从观察、研究到设计<br>翻阅完整 PDF</p><span class="module-en">DESIGN PORTFOLIO</span><span class="arrow" aria-hidden="true">↗</span></a></div></section></div><div class="home-bottom"><span class="hand">Small ideas. Real attempts.</span><span>在产品逻辑与设计表达之间，持续探索。</span></div>`;}
function internships(){return `${breadcrumb([['实习经历']])}${heading('WORK EXPERIENCE','在真实业务里，把问题想具体。','三段产品实习，分别关注 AI 体验、用户增长与交易策略。','Notes from real work.')}<div class="intern-layout"><aside class="side-index" aria-label="实习目录"><strong>实习目录</strong>${INTERNSHIPS.map((x,i)=>`<a href="#internships" data-jump="intern-${i}">${x.company}</a>`).join('')}<span class="muted">2025 — 2026</span></aside><div>${INTERNSHIPS.map((x,i)=>`<article class="experience" id="intern-${i}"><div class="experience-top"><span class="company-mark ${x.color}">${x.mark}</span><div><h2>${x.company}</h2><span class="role">${x.role}</span></div><time>${x.time}</time></div><p class="experience-summary">${x.summary}</p>${x.items.map(([h,p])=>`<div class="resume-item"><h3>${h}</h3><p>${p}</p></div>`).join('')}${tags(x.tags)}</article>`).join('')}</div></div>`;}
function vibe(){return `${breadcrumb([['Vibe Coding 项目']])}${heading('IDEAS INTO PRODUCTS','把想法，做成能使用的东西。','两个个人项目，记录从需求定义、规则设计到开发验证的完整过程。','Made with curiosity & Codex')}<div class="project-grid">${Object.entries(PROJECTS).map(([id,p])=>`<a href="#project/${id}" class="project-card"><div class="project-preview ${p.color}">${id==='hehao'?`<span class="scribble">A softer way<br>to say it.</span><img class="phone" src="${A+p.image}" alt="和好喵分享卡片示例"><img class="cat-small" src="${A}cat.webp" alt="" aria-hidden="true">`:`<img class="desktop" src="${A+p.image}" alt="衣柜设计师布局编辑界面">`}</div><div class="project-card-body"><span class="eyebrow">${p.en}</span><h2>${p.name}<span aria-hidden="true">↗</span></h2><p>${p.brief}</p>${tags(p.tags)}<div class="project-footer"><span>查看从 0 到 1 的过程</span><span>案例手记 →</span></div></div></a>`).join('')}</div>`;}
function project(id){const p=PROJECTS[id];if(!p)return notFound();const sections=[['overview','项目整体介绍'],['needs','发现与分析需求'],['prd','需求文档与交付'],['process','流程与规则策略'],['validation','评测与迭代'],['outcome','最终效果'],['future','市场化与商业化']];return `${breadcrumb([['Vibe Coding','#vibe'],[p.name]])}<section class="case-hero"><div><span class="eyebrow">${p.en} · PRODUCT CASE STUDY</span><h1>${p.name}</h1><p class="tagline">${p.tagline}</p><p class="lead">${p.brief}</p><div class="actions"><a class="button primary" href="${p.url}" target="_blank" rel="noopener">打开项目体验 ↗</a><button class="button" data-jump="process">阅读产品流程 ↓</button></div></div><div class="case-cover ${p.color}"><span class="paper-pin" aria-hidden="true">⌕</span><img src="${A+p.image}" alt="${p.name}实际界面"></div></section><dl class="case-meta">${p.meta.map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="case-layout"><aside class="side-index" aria-label="案例目录"><strong>这份案例里</strong>${sections.map(([k,v])=>`<a href="#project/${id}" data-jump="${k}">${v}</a>`).join('')}</aside><article><section id="overview" class="case-section"><span class="eyebrow">THE PRODUCT</span><h2>项目整体介绍</h2><p>${p.intro}</p>${tags(p.tags)}</section><section id="needs" class="case-section"><span class="eyebrow">FROM A REAL PROBLEM</span><h2>${p.storyTitle}</h2><p>${p.story}</p><div class="insight-grid">${p.insight.map(([h,t])=>`<div class="insight"><h3>${h}</h3><p>${t}</p></div>`).join('')}</div></section><section id="prd" class="case-section"><span class="eyebrow">MAKE THE NEEDS ACTIONABLE</span><h2>把需求变成可执行的产品定义</h2><p>先明确谁在什么场景下完成什么任务，再将流程、规则和验收条件沉淀为可交付的材料。</p><div class="deliverables">${p.deliverables.map(([h,t])=>`<div class="deliverable"><h3>${h}</h3><p>${t}</p></div>`).join('')}</div><div class="actions" style="margin-top:24px"><a href="assets/${id}-prd.md" class="button small" download>下载产品需求摘要 ↓</a></div></section><section id="process" class="case-section"><span class="eyebrow">FLOW & PRODUCT DECISIONS</span><h2>让流程背后的规则也能被看见</h2>${flow(p.flow)}${p.decisions.map(([h,t])=>`<div class="decision"><h3>${h}</h3><p>${t}</p></div>`).join('')}</section><section id="validation" class="case-section"><span class="eyebrow">EVALUATION & ITERATION</span><h2>${p.evidenceTitle}</h2><p>${p.evidence}</p><p class="note">${p.evidenceNote}</p><div class="badcases">${p.badcase.map(([h,t])=>`<div><h3>${h}</h3><p>${t}</p></div>`).join('')}</div></section><section id="outcome" class="case-section"><span class="eyebrow">WHAT IT LOOKS LIKE</span><h2>最终效果与关键界面</h2><div class="gallery">${p.shots.map(([src,h,t])=>figure(A+src,h,t)).join('')}</div><div class="actions" style="margin-top:24px"><a class="button" href="${p.url}" target="_blank" rel="noopener">在独立窗口体验项目 ↗</a></div></section><section id="future" class="case-section"><span class="eyebrow">AFTER THE FIRST VERSION</span><h2>如果正式推向市场<span class="planned">后续设想</span></h2><p>当前验证范围之外，继续把用户价值、运行成本和商业可行性连接起来。</p><div class="market-steps">${p.market.map(([h,t])=>`<div class="market-step"><h3>${h}</h3><p>${t}</p></div>`).join('')}</div><h3>下一阶段要观察什么</h3><div class="metrics">${p.metrics.map(m=>`<span>${m}</span>`).join('')}</div><p class="note">${p.next}</p></section><div class="case-next"><a href="#vibe">← 项目目录</a><a href="#project/${id==='hehao'?'wardrobe':'hehao'}">下一份手记：${id==='hehao'?'衣柜设计师':'和好喵'} →</a></div></article></div>`;}
const SCROLLS={zju:{name:'浙大校区',fallback:'scroll-12-1.png',key:'scroll-zju',caption:'浙大校区 · 唯美冬日风格 · 课程作品'},xihu:{name:'西湖十景',fallback:'scroll-15-1.png',key:'scroll-xihu',caption:'新西湖十景 · 赛博夜色风格 · 课程作品'},ningbo:{name:'宁波城区',fallback:'scroll-10-1.png',key:'scroll-ningbo',caption:'宁波城市长卷 · 马克笔风格（WebUI）· 同组探索'}};
function scrollStage(){const s=SCROLLS[state.scroll];return `<div class="scroll-tabs" role="tablist" aria-label="长卷主题">${Object.entries(SCROLLS).map(([id,x])=>`<button role="tab" aria-selected="${state.scroll===id}" data-scroll="${id}">${x.name}</button>`).join('')}</div><div class="scroll-stage"><div class="scroll-viewport" tabindex="0" aria-label="${s.name}长卷，使用触控板横向滚动或方向键浏览"><img src="${asset(s.key,s.fallback)}" alt="${s.caption}"></div><div class="scroll-caption"><span>${s.caption}</span><span>← 横向滚动，慢慢看 →</span><button data-image="${asset(s.key,s.fallback)}" data-title="${s.caption}">查看全卷 ↗</button></div></div>`;}
function emptyAsset(key,title,desc){const src=asset(key);return src?figure(src,title,'自行上传的素材，保存在当前浏览器。'):`<div class="empty-asset"><span class="empty-symbol" aria-hidden="true">▧ +</span><strong>${title}</strong><p>${desc}</p><button class="button small" data-upload="${key}">上传${title}</button></div>`;}
function aigc(sub='scroll'){if(!['scroll','ecommerce','industrial'].includes(sub))sub='scroll';const body=sub==='scroll'?`<section class="aigc-section"><div class="aigc-intro"><div><h2>把一座城，放进一幅长卷里。</h2><p>围绕浙大校区、西湖十景与宁波城区，尝试让不同来源的照片在同一构图、光照和风格中连续展开。</p><span class="tag">课程小组作品</span> <span class="tag">Photoshop / WebUI / ComfyUI</span></div></div><div class="subheading">First, the workflow / 先看工作流</div><div class="workflow-display">${figure(asset('scroll-workflow','scroll-workflow.png'),'课程汇报中的 ComfyUI 工作流','此前课程汇报中的工作流说明，包含风格参考、结构控制、采样及可选后处理。')}<div class="workflow-text"><ol><li><b>选景与预拼接：</b>先确定地标顺序，用 Photoshop 统一地平线、尺度与构图。</li><li><b>提取内容与风格：</b>参考图提供风格信息；原底图决定建筑与布局。</li><li><b>保留结构：</b>DepthAnything 与 LineArt 分别提供深度、轮廓约束。</li><li><b>采样与人工处理：</b>完成风格化后检查建筑、接缝、光照，再局部重绘或拼接修复。</li></ol><a href="assets/scroll-reproduction.json" download class="button small">下载后续复现工作流 ↓</a><p style="font-size:12px;margin-top:12px;color:var(--muted)">下载文件为后来整理的 Seedream 双图复现方案，非历史课程原始工作流；未以此声明已生成整幅长卷。</p></div></div><div class="subheading">Then, the result / 再看长卷效果</div><div id="scroll-content">${scrollStage()}</div><div class="subheading">Notes from the process / 工作流与产品思考</div><div class="reflection"><article><h3>先锁定不能变化的内容</h3><p>建筑数量、轮廓与相对位置比“更有画风”更重要。参考风格与内容底图需要分别约束，避免风格迁移变成重画地标。</p></article><article><h3>长卷质量看连续性</h3><p>单段好看并不保证整卷一致。需要看分段色彩、光照、尺度与接缝，再决定重绘、拼接还是人工修复。</p></article><article><h3>从生成走向可用工具</h3><p>将输入、必须保留的部分、候选对比与接受原因显式化。让用户能看懂和修改结果，才可能形成可靠的使用闭环。</p></article></div><details style="margin-top:24px"><summary>查看原汇报里的失败案例与处理</summary><div style="margin-top:20px">${figure(A+'scroll-badcase.png','课程汇报中的失败案例','保留结构、风格一致性和清晰度，是不同的检查对象。')}</div></details></section>`:sub==='ecommerce'?`<section class="aigc-section"><div class="aigc-intro"><div><h2>让生成结果服务商品表达。</h2><p>电商生图尝试的展示位，按“工作流 → 示例效果 → 检查与思考”组织。当前资料未找到对应原始工作流与成图，可在此补充。</p><span class="tag">素材待补充</span></div></div><div class="subheading">First, the workflow / ComfyUI 工作流</div>${emptyAsset('commerce-workflow','电商生图工作流','上传实际 ComfyUI 节点截图；这里不以示意流程冒充已完成工作流。')}<div class="subheading">Then, the result / 示例效果</div><div class="compare"><div>${emptyAsset('commerce-before','商品原图','建议使用同一商品的原始输入。')}</div><div>${emptyAsset('commerce-after','生图效果','放入该次工作流的真实输出。')}</div></div><div class="reflection"><article><h3>商品主体是否保真</h3><p>核对形状、颜色、材质、数量与标识。背景好看不能抵消商品信息被改动。</p></article><article><h3>修改是否在允许区域</h3><p>记录用户要求和不可修改区域；尝试固定主体、生成背景，再进行合成。</p></article><article><h3>让评价可追溯</h3><p>每轮保留输入、输出、拒绝原因与修改策略。这些为下一步评测设计，不是已获得的电商效果。</p></article></div></section>`:`<section class="aigc-section"><div class="aigc-intro"><div><h2>从平面草图，探索立体表达。</h2><p>先展示目前已经跑过的轻量图生图工作流，再呈现输入与输出。工业设计手绘和真实 3D 网格的完整案例仍可继续补充。</p><span class="tag">本地测试记录</span> <span class="tag">图生图 / 3D 观感效果图</span></div></div><div class="subheading">First, the workflow / ComfyUI 工作流</div><div class="workflow-display">${figure(asset('industrial-workflow','figurine-workflow.png'),'插画转手办效果的本地工作流','现有内置节点工作流。')}<div class="workflow-text"><ol><li><b>载入输入：</b>上传简单草图，等比缩放。</li><li><b>图生图采样：</b>在原轮廓基础上加入材质、体积与光照描述。</li><li><b>检查并导出：</b>核对角色、服饰和结构变化，保存 PNG。</li></ol><a class="button small" href="assets/figurine-workflow.json" download>下载现有工作流 JSON ↓</a></div></div><div class="subheading">Then, the result / 一次真实测试</div><div class="compare"><figure><img src="${asset('industrial-before','figurine-in.png')}" alt="ComfyUI自带的简笔人物测试输入"><figcaption>测试输入：ComfyUI 自带草图，非个人工业设计作品。</figcaption></figure><figure><img src="${asset('industrial-after','figurine-out.png')}" alt="本地生成的3D手办观感效果图"><figcaption>本地实际输出：有体积和塑料光影，但服饰发生变化。</figcaption></figure></div><p class="note" style="margin-top:24px">当前输出是 PNG 效果图，不是 GLB / OBJ 模型，也不能证明结构可制造。图生图在本例中改变了服饰，后续需补身份与结构约束。可用“替换素材”放入自己的工业设计草图与实际结果。</p><div class="reflection"><article><h3>外观与几何分开验证</h3><p>“看起来立体”只是视觉表达。可旋转网格、封闭性、尺度和拓扑需要另一套验收。</p></article><article><h3>保留设计意图</h3><p>用正侧视、关键比例、材质与结构约束减少漂移，记录失败样例而非只挑最好的一张。</p></article><article><h3>降低前期表达成本</h3><p>优先用于概念沟通与方向比较；工程结构与制造可行性仍需建模和专业确认。</p></article></div></section>`;return `${breadcrumb([['AIGC 尝试']])}${heading('GENERATIVE EXPLORATIONS','从工作流，到视觉表达。','','Process before pixels.')}<div class="tab-bar" role="tablist" aria-label="AIGC 分类">${[['scroll','风格化长卷'],['ecommerce','电商生图'],['industrial','手绘与立体表达']].map(([id,n])=>`<button role="tab" aria-selected="${id===sub}" data-route="aigc/${id}">${n}</button>`).join('')}</div>${body}`;}
function design(){const pdf=state.uploads.pdf;return `${breadcrumb([['软硬件系统设计作品集']])}${heading('DESIGN PORTFOLIO','翻开最初的设计探索。','保留完整作品集的叙事与排版，通过 PDF 直接阅读。','A book of beginnings.')}<div class="pdf-layout"><div class="pdf-book"><span>Selected Design Works</span><h2>观察。<br>思考。<br>设计。</h2>${icons.book}<small>Li Shilu / Portfolio</small></div><div class="pdf-copy"><span class="eyebrow">THE COMPLETE COLLECTION</span><h2>软硬件系统设计作品集</h2><p>创作于 2023 年保研期间。从问题观察、研究分析，到概念发展与设计表达。</p>${pdf?`<p class="file-name">▤ ${esc(pdf.name)} · ${(pdf.blob.size/1048576).toFixed(1)} MB</p><div class="actions"><a href="#pdf" class="button primary">在线阅读 PDF ↗</a><button class="button" data-upload="pdf">替换 PDF</button></div>`:`<div class="actions"><button class="button primary" data-upload="pdf">上传作品集 PDF ＋</button></div><p class="file-name">尚未放入保研作品集文件</p>`}<p id="upload-message" role="status"></p></div></div>`;}
function pdfReader(){if(!state.uploads.pdf)return design();return `${breadcrumb([['软硬件系统设计作品集','#design'],['在线阅读']])}<div class="reader-toolbar"><span class="file-name">${esc(state.uploads.pdf.name)}</span><div class="actions"><a class="button small" href="${state.urls.pdf}" target="_blank" rel="noopener">独立窗口打开 ↗</a><a class="button small" href="${state.urls.pdf}" download="${esc(state.uploads.pdf.name)}">下载 PDF ↓</a></div></div><section class="pdf-viewer" aria-label="PDF 在线阅读器"><div class="pdf-controls"><button class="button small" id="pdf-prev" data-pdf="prev" disabled>← 上一页</button><span id="pdf-page-count" aria-live="polite">正在加载 PDF…</span><button class="button small" id="pdf-next" data-pdf="next" disabled>下一页 →</button><button class="button small" data-pdf="minus" aria-label="缩小PDF">−</button><button class="button small" data-pdf="plus" aria-label="放大PDF">＋</button></div><div id="pdf-canvas-wrap"><canvas id="pdf-canvas" aria-label="PDF 当前页"></canvas></div><p id="pdf-read-status" role="status"></p></section><p class="note">文件在浏览器本地解析。也可使用“独立窗口打开”或下载阅读。</p>`;}
function notFound(){return `<div class="not-found"><span class="eyebrow">THIS PAGE IS STILL A BLANK SHEET</span><h1>这页手记还没有写下。</h1><p>回到目录，翻开另一页。</p><a class="button" href="#home">返回首页 →</a></div>`;}
function route(keepScroll=false){const parts=(location.hash.slice(1)||'home').split('/');const top=parts[0];const y=scrollY;const views={home,internships,vibe,aigc:()=>aigc(parts[1]),project:()=>project(parts[1]),design,pdf:pdfReader};main.innerHTML=(views[top]||notFound)();main.className='page-enter';if(top==='pdf'&&state.uploads.pdf)loadPDF();let active=top==='project'?'vibe':top==='pdf'?'design':top;document.querySelectorAll('[data-nav]').forEach(n=>{n.removeAttribute('aria-current');if(n.dataset.nav===active){n.setAttribute('aria-current','page');if(innerWidth<850)n.scrollIntoView({block:'nearest',inline:'center',behavior:'instant'});}});const names={home:'李诗璐 · 产品与设计手记',internships:'实习经历',vibe:'Vibe Coding 项目',aigc:'AIGC 尝试',design:'软硬件系统设计作品集',pdf:'PDF 在线阅读',project:PROJECTS[parts[1]]?.name||'项目'};document.title=(names[top]||'页面未找到')+(top==='home'?'':' · 李诗璐');if(!keepScroll){window.scrollTo({top:0,behavior:'instant'});}else window.scrollTo(0,y);}
const slots=[['portrait','首页个人照片','image'],['scroll-workflow','长卷工作流截图','image'],['scroll-zju','浙大长卷成图','image'],['scroll-xihu','西湖长卷成图','image'],['scroll-ningbo','宁波长卷成图','image'],['commerce-workflow','电商生图工作流','image'],['commerce-before','电商商品原图','image'],['commerce-after','电商生成效果','image'],['industrial-workflow','手绘 / 立体表达工作流','image'],['industrial-before','个人手绘输入','image'],['industrial-after','立体表达结果','image'],['pdf','保研作品集 PDF','pdf']];
let dbPromise;
function db(){return dbPromise??=new Promise((resolve,reject)=>{const request=indexedDB.open('shilu-portfolio',1);request.onupgradeneeded=()=>request.result.createObjectStore('assets');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error);});}
async function stored(mode,key,value){const d=await db();return new Promise((resolve,reject)=>{const tx=d.transaction('assets',mode);const st=tx.objectStore('assets');let request=value===undefined?st.get(key):value===null?st.delete(key):st.put(value,key);let result;request.onsuccess=()=>result=request.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error);});}
function installAsset(key,item){if(state.urls[key])URL.revokeObjectURL(state.urls[key]);if(item){state.uploads[key]=item;state.urls[key]=URL.createObjectURL(item.blob);}else{delete state.uploads[key];delete state.urls[key];}}
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('visible'),4500);}
async function upload(key,file){if(!file)return;try{const type=slots.find(x=>x[0]===key)?.[2];if(type==='pdf'){if(file.size>50*1024*1024)throw Error('PDF 超过 50 MB，请压缩后重试。');const head=new TextDecoder().decode(await file.slice(0,5).arrayBuffer());if(head!=='%PDF-')throw Error('文件不是有效的 PDF，请重新选择。');}else{if(file.size>15*1024*1024)throw Error('图片超过 15 MB，请压缩后重试。');if(!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('请选择 JPG、PNG 或 WebP 图片。');await createImageBitmap(file).then(b=>b.close());}const item={name:file.name,blob:file,type:file.type,date:new Date().toISOString()};await stored('readwrite',key,item);installAsset(key,item);renderEditor();route(true);toast('已保存到当前浏览器，可立即预览。');}catch(e){toast(e.message||'保存失败，请检查浏览器存储空间后重试。');const el=document.querySelector('#editor-status');el.textContent=e.message||'保存失败';}}
function filePicker(key){const input=document.createElement('input');input.type='file';input.accept=key==='pdf'?'application/pdf':'.png,.jpg,.jpeg,.webp';input.style.display='none';document.body.appendChild(input);input.onchange=async()=>{await upload(key,input.files[0]);input.remove();};input.addEventListener('cancel',()=>input.remove(),{once:true});input.click();}
function renderEditor(){document.querySelector('#editor-fields').innerHTML=slots.map(([id,name,type])=>`<div class="editor-row"><label for="file-${id}">${name}</label><input id="file-${id}" data-file="${id}" type="file" accept="${type==='pdf'?'application/pdf':'.png,.jpg,.jpeg,.webp'}"><small>${state.uploads[id]?esc(state.uploads[id].name):type==='pdf'?'尚未上传 PDF':'保留默认素材或待补充位置'}</small>${state.uploads[id]?`<button data-reset="${id}">移除本次上传，恢复默认</button>`:''}</div>`).join('');}
function openEditor(){renderEditor();document.querySelector('#editor-status').textContent='';document.querySelector('#editor').showModal();}
document.querySelector('#open-editor').onclick=openEditor;document.querySelector('#footer-editor').onclick=openEditor;
document.addEventListener('click',async e=>{if(e.target.closest('.skip')){e.preventDefault();main.focus();main.scrollIntoView({behavior:'instant'});return;}const close=e.target.closest('[data-close]');if(close){document.getElementById(close.dataset.close).close();return;}const image=e.target.closest('[data-image]');if(image){document.querySelector('#lightbox-image').src=image.dataset.image;document.querySelector('#lightbox-image').alt=image.dataset.title;document.querySelector('#lightbox-title').textContent=image.dataset.title;document.querySelector('#lightbox').showModal();return;}const go=e.target.closest('[data-route]');if(go){location.hash=go.dataset.route;return;}const jump=e.target.closest('[data-jump]');if(jump){e.preventDefault();document.getElementById(jump.dataset.jump)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const s=e.target.closest('[data-scroll]');if(s){state.scroll=s.dataset.scroll;document.querySelector('#scroll-content').innerHTML=scrollStage();return;}const up=e.target.closest('[data-upload]');if(up){filePicker(up.dataset.upload);return;}const reset=e.target.closest('[data-reset]');if(reset){try{await stored('readwrite',reset.dataset.reset,null);installAsset(reset.dataset.reset,null);renderEditor();route(true);toast('已恢复默认素材。');}catch{toast('移除失败，请重试。');}}});
document.addEventListener('change',e=>{if(e.target.dataset.file)upload(e.target.dataset.file,e.target.files[0]);});
for(const dialog of document.querySelectorAll('dialog'))dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}});
window.addEventListener('hashchange',()=>{route();main.focus({preventScroll:true});});
route();
(async()=>{try{for(const[id]of slots){const item=await stored('readonly',id);if(item?.blob)installAsset(id,item);}route(true);}catch{toast('浏览器存储不可用，已有作品仍可浏览。');}})();
let pdfTask=0,pdfDoc=null,pdfPage=1,pdfZoom=1,pdfRendering=false;
async function loadPDF(){const ticket=++pdfTask;pdfDoc=null;pdfPage=1;pdfZoom=1;try{const lib=await import('./assets/pdfjs/pdf.min.mjs');lib.GlobalWorkerOptions.workerSrc=new URL('./assets/pdfjs/pdf.worker.min.mjs',location.href).href;const data=await state.uploads.pdf.blob.arrayBuffer();const doc=await lib.getDocument({data,isEvalSupported:false,enableXfa:false}).promise;if(ticket!==pdfTask||!document.getElementById('pdf-canvas'))return;pdfDoc=doc;await drawPDF();}catch(e){const el=document.getElementById('pdf-read-status');if(el)el.textContent='当前文件无法在内嵌阅读器解析，请使用独立窗口打开，或更换未加密的PDF。';const c=document.getElementById('pdf-page-count');if(c)c.textContent='预览不可用';}}
async function drawPDF(){if(!pdfDoc||pdfRendering)return;pdfRendering=true;const canvas=document.getElementById('pdf-canvas');if(!canvas){pdfRendering=false;return;}const prev=document.getElementById('pdf-prev'),next=document.getElementById('pdf-next');prev.disabled=true;next.disabled=true;try{const page=await pdfDoc.getPage(pdfPage);const base=page.getViewport({scale:1});const fit=Math.min(1150,document.getElementById('pdf-canvas-wrap').clientWidth-32)/base.width;const ratio=Math.min(devicePixelRatio||1,2);const view=page.getViewport({scale:fit*pdfZoom});canvas.width=Math.floor(view.width*ratio);canvas.height=Math.floor(view.height*ratio);canvas.style.width=view.width+'px';canvas.style.height=view.height+'px';await page.render({canvasContext:canvas.getContext('2d'),viewport:view,transform:[ratio,0,0,ratio,0,0]}).promise;document.getElementById('pdf-page-count').textContent=pdfPage+' / '+pdfDoc.numPages+' 页';document.getElementById('pdf-read-status').textContent='';}catch{const el=document.getElementById('pdf-read-status');if(el)el.textContent='当前页渲染失败，可以下载PDF后阅读。';}finally{pdfRendering=false;if(document.contains(prev)){prev.disabled=pdfPage<=1;next.disabled=pdfPage>=pdfDoc.numPages;}}}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-pdf]');if(!b||!pdfDoc||pdfRendering)return;const action=b.dataset.pdf;if(action==='prev'&&pdfPage>1)pdfPage--;if(action==='next'&&pdfPage<pdfDoc.numPages)pdfPage++;if(action==='minus')pdfZoom=Math.max(.5,pdfZoom-.25);if(action==='plus')pdfZoom=Math.min(3,pdfZoom+.25);await drawPDF();});
